class LoanService:
    def process(self, member, book, action):
        # 회원 등급 체크
        if member.grade == 1:
            limit = 3
        elif member.grade == 2:
            limit = 5
        else:
            limit = 10

        if action == "borrow":
            # 대출 가능 여부 검사
            current_loans = 0
            for loan in member.loans:
                if loan.status == "active":
                    current_loans += 1
            if current_loans >= limit:
                return {"ok": False, "error": "limit"}
            for loan in member.loans:
                if loan.status == "active" and (datetime.now() - loan.borrowed_at).days > 14:
                    return {"ok": False, "error": "overdue"}
            # 대출 생성
            loan = Loan(member=member, book=book, status="active", borrowed_at=datetime.now())
            book.stock = book.stock - 1
            book.save()
            loan.save()
            send_email(member.email, "borrowed")
            return {"ok": True, "loan_id": loan.id}
        elif action == "return":
            loan = Loan.objects.get(member=member, book=book, status="active")
            days = (datetime.now() - loan.borrowed_at).days
            if days > 14:
                fee = (days - 14) * 100
            else:
                fee = 0
            loan.status = "returned"
            loan.save()
            book.stock = book.stock + 1
            book.save()
            return {"ok": True, "fee": fee}
        else:
            return {"ok": False, "error": "unknown"}
