class Loan:
    def __init__(self, member, book, borrowed_at, returned_at=None, status="active"):
        self.member = member
        self.book = book
        self.borrowed_at = borrowed_at
        self.returned_at = returned_at
        self.status = status
        self.fee = 0

    def calculate_fee(self):
        if self.returned_at is None:
            now = datetime.now()
        else:
            now = self.returned_at
        days = (now - self.borrowed_at).days
        # 연체료: 14일 초과 시 일당 100원
        if days > 14:
            if self.member is not None:
                if self.member.grade == "VIP":
                    self.fee = (days - 14) * 50
                else:
                    self.fee = (days - 14) * 100
            else:
                self.fee = 0
        else:
            self.fee = 0
        return self.fee

    def extend(self):
        if self.member.grade == "normal":
            return False
        if self.member.grade == "premium" or self.member.grade == "VIP":
            self.borrowed_at = self.borrowed_at + timedelta(days=7)
            return True
        return False
